// Explicit env: PLAYWRIGHT_MODULE, GITDASH_TEST_ORIGIN, GITDASH_TEST_OUTPUT, GITDASH_TEST_FIXTURE.
const assert=require('node:assert/strict'),fs=require('node:fs/promises');const {chromium}=require(process.env.PLAYWRIGHT_MODULE);
(async()=>{
 const fixture=JSON.parse(await fs.readFile(process.env.GITDASH_TEST_FIXTURE,'utf8')),origin=process.env.GITDASH_TEST_ORIGIN,output=process.env.GITDASH_TEST_OUTPUT;assert.ok(origin&&output);await fs.mkdir(output,{recursive:true});
 const browser=await chromium.launch({headless:true}),page=await browser.newPage({viewport:{width:1440,height:1000},timezoneId:'Asia/Tokyo'}),errors=[],passed=[];page.on('pageerror',e=>errors.push(e.message));page.setDefaultTimeout(20000);
 const download=async(scope,name)=>{const event=page.waitForEvent('download');await scope.getByRole('button',{name,exact:true}).click();return fs.readFile(await(await event).path());};
 const capture=async(scope,name)=>{await scope.locator('summary').first().scrollIntoViewIfNeeded();await scope.screenshot({path:`${output}/${name}.png`,style:'.agent-timeline-sidebar { visibility:hidden !important; }'});await page.setViewportSize({width:390,height:844});await scope.locator('summary').first().scrollIntoViewIfNeeded();await scope.screenshot({path:`${output}/${name}-mobile.png`,style:'.agent-timeline-sidebar { visibility:hidden !important; }'});assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),`${name} mobile overflow`);await page.setViewportSize({width:1440,height:1000});};
 try{
  await page.goto(`${origin}/project?path=${encodeURIComponent(fixture.path)}&tab=files&range=current`);
  const content=page.locator('.content-search');await content.locator('summary').click();await content.getByLabel('内容検索のリビジョン',{exact:true}).fill('main');await content.getByLabel('内容検索の検索語',{exact:true}).fill('Needle');await content.getByRole('button',{name:'内容を検索',exact:true}).click();await page.waitForFunction(()=>document.querySelectorAll('.content-search-table tbody tr').length===4);
  await content.getByLabel('大文字・小文字を区別',{exact:true}).check();await content.getByRole('button',{name:'内容を検索',exact:true}).click();await page.waitForFunction(()=>document.querySelectorAll('.content-search-table tbody tr').length===3);
  await content.getByLabel('内容検索のディレクトリ',{exact:true}).fill('src');await content.getByRole('button',{name:'内容を検索',exact:true}).click();await page.waitForFunction(()=>document.querySelectorAll('.content-search-table tbody tr').length===2);
  await content.getByRole('button',{name:'src/alpha.txt 1行の前後を表示',exact:true}).click();await content.locator('.content-search-context-line.is-match').waitFor();assert.ok((await content.locator('.content-search-context').innerText()).includes('needle lower'));assert.ok((await content.getByRole('link',{name:'固定した版でファイル履歴を調べる（自動取得しない）',exact:true}).getAttribute('href')).includes(fixture.revision));
  const csv=(await download(content,'一致する行をCSV保存')).toString();assert.ok(csv.includes('src/alpha.txt')&&csv.includes('Needle first')&&!csv.includes('docs/beta.md'));
  await content.locator('.content-search-preview').screenshot({path:`${output}/content-context.png`});await capture(content,'content-search');await content.getByRole('link',{name:'固定した版でファイル履歴を調べる（自動取得しない）',exact:true}).click();await page.waitForFunction(()=>document.querySelector('[aria-label="ファイル履歴のファイル相対パス"]')?.value==='src/alpha.txt');assert.equal(await page.getByLabel('ファイル履歴のリビジョン',{exact:true}).inputValue(),fixture.revision);assert.equal(await page.locator('.file-history-table').count(),0);
  passed.push('Pinned literal content search, case mode, directory scope, matching-line context, immutable history handoff without execution, CSV bytes');
  await page.goto(`${origin}/project?path=${encodeURIComponent(fixture.path)}&tab=files&range=current`);
  // Capture only the inspected panel; hide the unrelated global timeline only during screenshots.
  const ignore=page.locator('.ignore-inspector');await ignore.locator('summary').click();await ignore.getByRole('button',{name:'一覧を取得',exact:true}).click();const inventory=ignore.locator('#ignore-inventory-title').locator('..').locator('..').locator('..');
  await page.waitForFunction(()=>document.querySelectorAll('.ignore-inspector-table tbody tr').length===3);
  await ignore.getByLabel('無視済みファイル一覧をディレクトリで絞り込み',{exact:true}).selectOption('src');assert.equal(await ignore.locator('tbody tr').count(),1);assert.ok((await ignore.locator('tbody').innerText()).includes('secret note.tmp'));
  await ignore.getByLabel('無視済みファイル一覧を検索',{exact:true}).fill('absent');assert.equal(await ignore.locator('tbody tr').count(),0);await ignore.getByRole('button',{name:'絞り込みを解除',exact:true}).click();assert.equal(await ignore.locator('tbody tr').count(),3);
  const ignoredCsv=(await download(ignore,'表示中をCSV保存')).toString();assert.ok(ignoredCsv.includes('cache/generated.txt')&&ignoredCsv.includes('src/.gitignore'));
  await ignore.getByLabel('ignoreルールを調べる候補パス',{exact:true}).fill('debug.log\nkeep.log\ntracked.log\nplain.txt');await ignore.getByRole('button',{name:'候補を判定',exact:true}).click();await page.waitForFunction(()=>document.querySelectorAll('.ignore-inspector-table').length===2);
  const diagnosis=ignore.locator('.ignore-inspector-table').nth(1);assert.equal(await diagnosis.locator('tbody tr').count(),4);assert.ok((await diagnosis.locator('tr').filter({hasText:'tracked.log'}).innerText()).includes('追跡済み'));assert.ok((await diagnosis.locator('tr').filter({hasText:'keep.log'}).innerText()).includes('否定ルール'));
  const diagnosisCsv=(await download(ignore,'判定をCSV保存')).toString();assert.ok(diagnosisCsv.includes('tracked.log')&&diagnosisCsv.includes('!keep.log'));await capture(ignore,'ignore-inspector');await ignore.locator('summary').click();
  passed.push('Ignored untracked inventory, directory/search filtering, exact rule source and negation, tracked-rule distinction, inventory/diagnosis CSV');
  const attributes=page.locator('.file-attributes');if(await attributes.getAttribute('open')===null)await attributes.locator('summary').click();await attributes.locator('.file-attributes-table tbody tr').first().waitFor();
  await attributes.getByLabel('改行情報のフィルター',{exact:true}).selectOption('mixed');assert.ok((await attributes.locator('.file-attributes-table tbody').innerText()).includes('mixed.dat'));
  await attributes.getByLabel('改行情報のフィルター',{exact:true}).selectOption('all');await attributes.getByLabel('改行情報をディレクトリで絞り込み',{exact:true}).selectOption('src');assert.ok(!(await attributes.locator('.file-attributes-table tbody').innerText()).includes('plain.txt'));await attributes.getByLabel('改行情報をディレクトリで絞り込み',{exact:true}).selectOption('/');
  await attributes.getByLabel('src/alpha.txtを属性調査に含める',{exact:true}).check();await attributes.getByLabel('plain.txtを属性調査に含める',{exact:true}).check();await attributes.getByRole('button',{name:'選択した 2 件を調べる',exact:true}).click();await page.waitForFunction(()=>document.querySelectorAll('.file-attributes-attribute-card').length===2);assert.ok((await attributes.locator('.file-attributes-attribute-list').innerText()).includes('crlf'));
  const compare=attributes.locator('.file-attributes-compare');await compare.locator('.file-attributes-compare-controls select').nth(0).selectOption('src/alpha.txt');await compare.locator('.file-attributes-compare-controls select').nth(1).selectOption('plain.txt');assert.ok((await compare.locator('.file-attributes-compare-result').innerText()).includes('custom'));
  await compare.locator('.file-attributes-compare-result').screenshot({path:`${output}/attributes-comparison.png`});await capture(attributes,'file-attributes');const attrCsv=(await download(attributes,'現在の一覧をCSV保存')).toString();assert.ok(attrCsv.includes('src/alpha.txt')&&attrCsv.includes('custom')&&attrCsv.includes('crlf'));
  await attributes.getByLabel('Git属性を評価する対象',{exact:true}).selectOption('index');await attributes.getByRole('button',{name:'選択した 2 件を調べる',exact:true}).click();await attributes.locator('.file-attributes-inspection-meta').filter({hasText:'index（ステージ）'}).waitFor();const attrText=await attributes.locator('.file-attributes-attribute-list').innerText();assert.ok(attrText.includes('lf')&&!attrText.includes('crlf'));
  passed.push('Index/worktree EOL inventory, mixed and directory filters, selected effective attributes in explicit worktree/index modes, two-path comparison, CSV');
  // Delay a real attribute response, change its input, then verify it cannot reappear under the new mode.
  let signalCaptured,releaseResponse,responseReleased;const captured=new Promise(resolve=>signalCaptured=resolve),gate=new Promise(resolve=>releaseResponse=resolve),released=new Promise(resolve=>responseReleased=resolve);
  await page.route('**/api/repo/attributes',async route=>{try{const response=await route.fetch();signalCaptured();await gate;try{await route.fulfill({response});}catch{/* The correct implementation may have aborted the request. */}}finally{responseReleased();}});
  await attributes.getByLabel('Git属性を評価する対象',{exact:true}).selectOption('worktree');await attributes.getByRole('button',{name:'選択した 2 件を調べる',exact:true}).click();await captured;await attributes.getByLabel('Git属性を評価する対象',{exact:true}).selectOption('index');releaseResponse();await released;await page.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve))));assert.equal(await attributes.locator('.file-attributes-attribute-card').count(),0);await page.unroute('**/api/repo/attributes');
  await content.locator('summary').click();await content.getByLabel('内容検索のリビジョン',{exact:true}).fill('main');await content.getByLabel('内容検索の検索語',{exact:true}).fill('NO_MATCH_FOR_THIS_FIXTURE');await content.getByRole('button',{name:'内容を検索',exact:true}).click();await content.getByText('一致する行はありません。',{exact:true}).waitFor();await content.getByLabel('内容検索のリビジョン',{exact:true}).fill('--help');await content.getByRole('button',{name:'内容を検索',exact:true}).click();await content.getByRole('alert').waitFor();assert.equal(await content.getByText('一致する行はありません。',{exact:true}).count(),0);
  passed.push('Delayed attribute result discarded after mode change; successful empty content search distinct from invalid-revision failure');
  assert.deepEqual(errors,[]);await fs.writeFile(`${output}/result.json`,JSON.stringify({origin,fixture:fixture.path,passed,errors},null,2));console.log({passed,errors});
 }catch(e){console.error(e);console.error(await page.evaluate(()=>({width:innerWidth,scroll:document.documentElement.scrollWidth,overflow:[...document.querySelectorAll('body *')].filter(e=>e.getBoundingClientRect().right>innerWidth+1).slice(-15).map(e=>({tag:e.tagName,cls:e.className,right:e.getBoundingClientRect().right,width:e.getBoundingClientRect().width}))})));await page.screenshot({path:`${output}/failure.png`});console.error((await page.locator('body').innerText()).slice(-3000));process.exitCode=1;}finally{await browser.close();}
})();
